fn search_lane()->(usize,usize){let lane=std::env::var("SEARCH_LANE").unwrap().parse::<usize>().unwrap();let lanes=std::env::var("SEARCH_LANES").unwrap().parse::<usize>().unwrap();assert_eq!(lanes,4);assert!(lane<lanes);(lane,lanes)}
fn bind_operational_args(first:u64,count:usize,lookahead:usize){assert_eq!(first,1);assert_eq!(lookahead,4096);assert_eq!(count,134217728);assert_eq!(count%lookahead,0);}
fn window_start(first:u64,window:usize,lookahead:usize)->u64{let(lane,lanes)=search_lane();first+(window*lanes+lane*lookahead)as u64}
fn stop_after()->Option<u64>{let p=std::env::var("SEARCH_STOP_FILE").unwrap();match std::fs::read_to_string(p){Ok(s)=>Some(s.trim().parse().unwrap()),Err(e)if e.kind()==std::io::ErrorKind::NotFound=>None,Err(e)=>panic!("stop marker unreadable: {e}")}}
fn record_window(start:u64,count:usize,total:usize){let p=std::env::var("SEARCH_PROGRESS_FILE").unwrap();let tmp=format!("{p}.tmp");let row=serde_json::json!({"status":"COMPLETE_WINDOW_ALL_ROWS_RECORDED","first":start,"last":start+count as u64-1,"count":count,"cumulative_worker_rows":total,"lane":search_lane().0});std::fs::write(&tmp,format!("{row}\n")).unwrap();std::fs::rename(tmp,p).unwrap();}
fn record_pass(nonce:u64){let dir=std::env::var("SEARCH_PASS_DIR").unwrap();let path=std::path::Path::new(&dir).join(format!("pass-{nonce}.json"));let tmp=path.with_extension("tmp");let row=serde_json::json!({"nonce":nonce,"full_protected9024_pass":true,"selection":"lowest passing nonce after all lower intervals complete; no Toffoli selection"});std::fs::write(&tmp,format!("{row}\n")).unwrap();std::fs::rename(tmp,path).unwrap();}
fn bind_operational(){let path=std::env::var("ACCEPTANCE_PATH").unwrap();let expected=std::env::var("ACCEPTANCE_SHA256").unwrap();sha_check(&path,&expected);let row:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();assert_eq!(row["status"],"SOURCE_BOUND_MASK_TRANSFER_AND_RUNTIME_ACCEPTED_FOR_ASCENDING_SEARCH");assert_eq!(row["candidate_stream_sha256"],"9f50f06098026882a57f5f6c436abaaf68be79be2fc7c6e33b8e884065195a3a");assert_eq!(row["mask_sha256"],"560c12d5044dd895a4ef32adc905cdde48a780a196b3b28a75951c7f27b4fe9d");assert_eq!(row["lowest_pass_from"],1);assert_eq!(row["submission_mode"],"queue");assert_eq!(row["cost_gate_pass"],true);assert_eq!(row["failure_gate_pass"],true);search_lane();}
#[cfg(test)]mod search_order_tests{#[test]fn interleaved_windows_partition_exact_ascending_prefix(){for lookahead in [1usize,9,4096]{let mut ranges=Vec::new();for window in 0..5{for lane in 0..4{let start=1+(window*4+lane)*lookahead;ranges.push((start,start+lookahead-1));}}ranges.sort();assert_eq!(ranges[0].0,1);for pair in ranges.windows(2){assert_eq!(pair[0].1+1,pair[1].0);}assert_eq!(ranges.last().unwrap().1,20*lookahead);}}}
